import { codeManagementRoutes } from "@/modules/system/code/routes";
import { permissionManagementRoutes } from "@/modules/system/permissions/routes";
import { pqRouteGroupLabels, pqRouteLeafLabels } from "@/modules/pq/routes";

const codeRouteLabels = Object.fromEntries(codeManagementRoutes.map((route) => [route.pathSegment, route.label]));
const permissionRouteLabels = Object.fromEntries(permissionManagementRoutes.map((route) => [route.pathSegment, route.label]));

export const routeLabelBySegment: Record<string, string> = {
  dashboard: "대시보드",
  system: "시스템관리",
  code: "코드관리",
  permissions: "권한관리",
  pq: "PQ관리",
  notifications: "공지사항 관리",
  users: "사용자관리",
  "basic-info": "기본정보",
  "construction-types": "공사종류",
  ...pqRouteGroupLabels,
  ...pqRouteLeafLabels,
  ...codeRouteLabels,
  ...permissionRouteLabels,
  "engineer-personal-info": "기술자 인사 정보",
};

export type BreadcrumbItem = {
  current: boolean;
  href?: string;
  label: string;
};

export function getPathSegments(pathname: string) {
  return pathname.split("/").filter(Boolean);
}

export function getPageLabel(pathname: string) {
  if (pathname === "/" || pathname === "/dashboard") {
    return "대시보드";
  }

  const segments = getPathSegments(pathname);
  const leafSegment = segments.at(-1);

  if (!leafSegment) {
    return "대시보드";
  }

  return routeLabelBySegment[leafSegment] ?? decodeURIComponent(leafSegment);
}

export function getBreadcrumbItems(pathname: string): BreadcrumbItem[] {
  if (pathname === "/" || pathname === "/dashboard") {
    return [{ current: true, label: "대시보드" }];
  }

  const segments = getPathSegments(pathname);

  return [
    { current: false, href: "/dashboard", label: "대시보드" },
    ...segments.map((segment, index) => ({
      current: index === segments.length - 1,
      href: `/${segments.slice(0, index + 1).join("/")}`,
      label: routeLabelBySegment[segment] ?? decodeURIComponent(segment),
    })),
  ];
}
